def clip_probability(value: float) -> float:
    if not isinstance(value, (int, float)) or not 0 <= value <= 1:
        raise ValueError("Expected a finite number between 0 and 1")
    return min(0.99, max(0.01, float(value)))
assert clip_probability(0) == 0.01
assert clip_probability(0.4) == 0.4
assert clip_probability(1) == 0.99
try:
    clip_probability(float("nan"))
except ValueError:
    print("Invalid input rejected; all checks passed")
